from pathlib import Path
p=Path(__file__).parent;s=(p/'force_filter32_seed.hpp').read_text() if(p/'force_filter32_seed.hpp').exists()else(p/'force_filter32_reduce.hpp').read_text()
include='''#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
#include <immintrin.h>
#endif
'''
s=s.replace('#include <type_traits>', '#include <type_traits>\n'+include)
helper='''#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
namespace reinsirk::detail {
[[gnu::target("avx2")]] inline bool primality32_avx2(std::uint32_t n, std::uint32_t odd, unsigned shifts) noexcept {
    std::uint32_t inverse=(3u*n)^2u;
    for(unsigned i=0;i<3;++i)inverse*=2u-n*inverse;
    const auto nn=_mm256_set1_epi64x(n),inv=_mm256_set1_epi64x(0u-inverse),zero=_mm256_setzero_si256();
    const auto lowmask=_mm256_set1_epi64x(UINT32_MAX);
    const auto limit=_mm256_set1_epi64x(std::uint64_t(n)-1);
    const auto mul=[&](__m256i a,__m256i b) __attribute__((target("avx2"))) {
        auto product=_mm256_mul_epu32(a,b);
        auto factor=_mm256_mul_epu32(product,inv);
        auto correction=_mm256_mul_epu32(factor,nn);
        auto carry=_mm256_srli_epi64(_mm256_sub_epi64(zero,_mm256_and_si256(product,lowmask)),63);
        auto result=_mm256_add_epi64(_mm256_add_epi64(_mm256_srli_epi64(product,32),_mm256_srli_epi64(correction,32)),carry);
        return _mm256_sub_epi64(result,_mm256_and_si256(_mm256_cmpgt_epi64(result,limit),nn));
    };
    const auto one=std::uint32_t((std::uint64_t{1}<<32)%n);
    const auto r2=std::uint32_t(std::uint64_t(one)*one%n);
    const auto ones=_mm256_set1_epi64x(one),minus=_mm256_set1_epi64x(n-one);
    auto result=ones,base=mul(_mm256_set_epi64x(2,61,7,2),_mm256_set1_epi64x(r2));
    for(auto e=odd;;){if(e&1u)result=mul(result,base);e>>=1;if(!e)break;base=mul(base,base);}
    auto passed=_mm256_or_si256(_mm256_cmpeq_epi64(result,ones),_mm256_cmpeq_epi64(result,minus));
    if((_mm256_movemask_pd(_mm256_castsi256_pd(passed))&7)==7)return true;
    for(unsigned i=1;i<shifts;++i){result=mul(result,result);passed=_mm256_or_si256(passed,_mm256_cmpeq_epi64(result,minus));if((_mm256_movemask_pd(_mm256_castsi256_pd(passed))&7)==7)return true;}
    return false;
}
}
#endif
'''
s=s.replace('#ifndef SIRKIT_PRIMALITY32_DEFINED',helper+'\n#ifndef SIRKIT_PRIMALITY32_DEFINED',1)
needle='''#if (defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    // R=2^64。'''
replacement='''#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
    if(n>61 && __builtin_cpu_supports("avx2")) return primality32_avx2(n,odd,shifts);
#endif
#if (defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    // R=2^64。'''
assert needle in s;s=s.replace(needle,replacement,1);(p/'simd.hpp').write_text(s)

