        u64 result = one_;
        for (;;) {
            if (exponent & 1u) result = multiply(result, base);
            exponent >>= 1;
            if (!exponent) return result;
            base = multiply(base, base);
        }
    }
''',
 'left':'''    u64 power(u64 base, u64 exponent) const noexcept {
        u64 result = base;
        for (unsigned bit = std::bit_width(exponent) - 1; bit-- > 0;) {
            result = multiply(result, result);
            if ((exponent >> bit) & 1u) result = multiply(result, base);
