#include <cstdio>
#include <random>
#include <vector>
using boost::multiprecision::cpp_int;using U=std::uint64_t;
template<class V>bool reference(U n,const V& bases){if(n<2)return false;if(!(n&1))return n==2;U d=n-1;unsigned s=std::countr_zero(d);d>>=s;for(auto base:bases){cpp_int b=base;b%=n;if(b<0)b+=n;if(b==0)continue;cpp_int v=1,p=b;for(U e=d;e;e>>=1){if(e&1)v=v*p%n;p=p*p%n;}if(v==1||v==n-1)continue;unsigned k=1;for(;k<s;++k){v=v*v%n;if(v==n-1)break;}if(k==s)return false;}return true;}
int main(){std::mt19937_64 rng(932421);std::array<U,7> bases{2,325,9375,28178,450775,9780504,1795265022};std::array<std::int64_t,7> neg{INT64_MIN,-3,-2,-1,0,7,INT64_MAX};std::vector<U> ns;for(U i=0;i<10000;++i)ns.push_back(i);for(U x:{U{1}<<32,U{4759123141},U{1}<<62,U{1}<<63,UINT64_MAX})for(U d=0;d<130;++d){ns.push_back(x-d);if(x<UINT64_MAX-d)ns.push_back(x+d);}for(int i=0;i<4000;++i){U x=rng();if(i%3==0)x&=UINT32_MAX;else if(i%3==1)x>>=2;ns.push_back(x);}for(auto n:ns){assert(is_prime(n)==reference(n,bases));if(n&1){assert(MillerRabin(n,neg)==reference(n,neg));}}for(auto n:{std::int64_t{-7},INT64_MIN,std::int64_t{-1}})assert(!is_prime(n)&&!MillerRabin(n,bases));std::printf("PASS %zu\n",ns.size());}

