            for (; step < shifts_; ++step)
            {
                value = normalize(multiply(value, value));
                if (value == modulus_ - one_)
                    break;
            }
            if (step == shifts_)
                return false;
        }
        return true;
    }
};
} // namespace reinsirk::detail
#endif

#ifndef SIRKIT_MILLER_RABIN_DEFINED
