// SPDX-License-Identifier: CC0-1.0

#include <bit>
#include <cstdint>
#include <initializer_list>
#include <limits>
#include <type_traits>
#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
#include <immintrin.h>
#endif


#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
namespace reinsirk::detail {
[[gnu::target("avx2")]] inline bool primality32_avx2(std::uint32_t n, std::uint32_t odd, unsigned shifts) noexcept {
    std::uint32_t inverse=(3u*n)^2u;
    for(unsigned i=0;i<3;++i)inverse*=2u-n*inverse;
    const auto nn=_mm256_set1_epi64x(n),inv=_mm256_set1_epi64x(0u-inverse),zero=_mm256_setzero_si256();
    const auto lowmask=_mm256_set1_epi64x(UINT32_MAX);
    const auto limit=_mm256_set1_epi64x(std::uint64_t(n)-1);
    const auto mul=[&](__m256i a,__m256i b) __attribute__((target("avx2"))) {
        auto product=_mm256_mul_epu32(a,b);
        auto factor=_mm256_mul_epu32(product,inv);
        auto correction=_mm256_mul_epu32(factor,nn);
        auto carry=_mm256_srli_epi64(_mm256_sub_epi64(zero,_mm256_and_si256(product,lowmask)),63);
        auto result=_mm256_add_epi64(_mm256_add_epi64(_mm256_srli_epi64(product,32),_mm256_srli_epi64(correction,32)),carry);
        return _mm256_sub_epi64(result,_mm256_and_si256(_mm256_cmpgt_epi64(result,limit),nn));
    };
    const auto one=std::uint32_t((std::uint64_t{1}<<32)%n);
    const auto r2=std::uint32_t(std::uint64_t(one)*one%n);
    const auto ones=_mm256_set1_epi64x(one),minus=_mm256_set1_epi64x(n-one);
    auto result=ones,base=mul(_mm256_set_epi64x(2,61,7,2),_mm256_set1_epi64x(r2));
    for(auto e=odd;;){if(e&1u)result=mul(result,base);e>>=1;if(!e)break;base=mul(base,base);}
    auto passed=_mm256_or_si256(_mm256_cmpeq_epi64(result,ones),_mm256_cmpeq_epi64(result,minus));
    if((_mm256_movemask_pd(_mm256_castsi256_pd(passed))&7)==7)return true;
    for(unsigned i=1;i<shifts;++i){result=mul(result,result);passed=_mm256_or_si256(passed,_mm256_cmpeq_epi64(result,minus));if((_mm256_movemask_pd(_mm256_castsi256_pd(passed))&7)==7)return true;}
    return false;
}
}
#endif

#ifndef SIRKIT_PRIMALITY32_DEFINED
#define SIRKIT_PRIMALITY32_DEFINED
namespace reinsirk::detail {
// uint32_t全域の素数判定。Miller-Rabinの底2,7,61を使う。
// 理論参考: G. Jaeschke (1993), https://doi.org/10.1090/S0025-5718-1993-1192971-8
inline bool is_prime_u32(std::uint32_t n) noexcept
{
    // 競技プログラミングでよく使う素数は、累乗計算を省く。
    switch (n)
    {
    case 167772161u:
    case 469762049u:
    case 754974721u:
    case 998244353u:
    case 1000000007u:
    case 1000000009u:
    case 1004535809u:
    case 1224736769u:
    case 2013265921u:
        return true;
    default:
        break;
    }
    if (n < 2)
        return false;
    if (n % 2u == 0) return n == 2u;
    if (n % 3u == 0) return n == 3u;
    if (n % 5u == 0) return n == 5u;
    if (n % 7u == 0) return n == 7u;
    if (n % 11u == 0) return n == 11u;
    std::uint32_t odd = n - 1;
    unsigned shifts = 0;
    while ((odd & 1u) == 0)
    {
        odd >>= 1;
        ++shifts;
    }
#if (defined(__GNUC__) || defined(__clang__)) && (defined(__x86_64__) || defined(__i386__)) && !defined(SIRKIT_DISABLE_SIMD)
    if(n>61 && __builtin_cpu_supports("avx2")) return primality32_avx2(n,odd,shifts);
#endif
#if (defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    // R=2^64。n<2^32なので、累乗中の剰余は2n未満のまま保持できる。
    using u64 = std::uint64_t;
    using u128 = __uint128_t; // GCC/Clangの128ビット整数拡張。
    u64 inverse = n;
    for (int i = 0; i < 5; ++i) inverse *= 2u - u64(n) * inverse;
    const u64 negative_inverse = u64{0} - inverse;
    const auto multiply = [n, negative_inverse](u64 a, u64 b) {
        const u128 product = static_cast<u128>(a) * b;
        const u128 correction = static_cast<u128>(static_cast<u64>(product) * negative_inverse) * n;
        return static_cast<u64>((product + correction) >> 64);
    };
    const u64 one = (u64{0} - n) % n;
    const u64 r_squared = one * one % n;
    for (std::uint32_t base : {2u, 7u, 61u}) {
        if (base % n == 0) continue;
        u64 value = one, power = multiply(base % n, r_squared);
        for (std::uint32_t exponent = odd; exponent; exponent >>= 1) {
            if (exponent & 1u) value = multiply(value, power);
            power = multiply(power, power);
        }
        if (value >= n) value -= n;
        if (value == one || value == n - one) continue;
        unsigned step = 1;
        for (; step < shifts; ++step) {
            value = multiply(value, value);
            if (value >= n) value -= n;
            if (value == n - one) break;
        }
        if (step == shifts) return false;
    }
#else
    // R=2^32のMontgomery乗算。33ビットの還元結果もuint64_tで扱う。
    std::uint32_t inverse = n;
    for (int i = 0; i < 5; ++i)
        inverse *= 2u - n * inverse;
    const std::uint32_t negative_inverse = 0u - inverse;
    const auto multiply = [n, negative_inverse](std::uint32_t a, std::uint32_t b)
    {
        const std::uint64_t product = static_cast<std::uint64_t>(a) * b;
        const std::uint32_t factor = static_cast<std::uint32_t>(product) * negative_inverse;
        const std::uint64_t correction = static_cast<std::uint64_t>(factor) * n;
        std::uint64_t result = (product >> 32) + (correction >> 32) +
                               (static_cast<std::uint32_t>(product) != 0);
        if (result >= n)
            result -= n;
        return static_cast<std::uint32_t>(result);
    };
    const auto one = static_cast<std::uint32_t>((std::uint64_t{1} << 32) % n);
    const auto r_squared = static_cast<std::uint32_t>(static_cast<std::uint64_t>(one) * one % n);
    for (std::uint32_t base : {2u, 7u, 61u})
    {
        if (base % n == 0)
            continue;
        std::uint32_t value = one, power = multiply(base % n, r_squared);
        for (std::uint32_t exponent = odd; ;)
        {
            if (exponent & 1u)
                value = multiply(value, power);
            exponent >>= 1;
            if (exponent == 0) break;
            power = multiply(power, power);
        }
        if (value == one || value == n - one)
            continue;
        unsigned step = 1;
        for (; step < shifts; ++step)
        {
            value = multiply(value, value);
            if (value == n - one)
                break;
        }
        if (step == shifts)
            return false;
    }
#endif
    return true;
}
} // namespace reinsirk::detail
#endif

// C++20以降。64ビット整数用の内部演算。状態は判定ごとに持つ。
#ifndef SIRKIT_MILLER_RABIN64_DEFINED
#define SIRKIT_MILLER_RABIN64_DEFINED
namespace reinsirk::detail {
template <bool Relaxed>
class MillerRabin64
{
    using u64 = std::uint64_t;
#if (defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
    using u128 = __uint128_t; // GCC/Clangの拡張。未対応環境では下の標準実装を使う。
#else
    struct Wide
    {
        u64 low, high;
    };
#endif
    const u64 modulus_;
    u64 negative_inverse_, one_, r_squared_;
    u64 odd_;
    unsigned shifts_ = 0;

#if !((defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC))
    // 128ビット整数のない環境では32ビットずつに分けて積を得る。
    static Wide product(u64 a, u64 b) noexcept
    {
        const u64 a0 = static_cast<std::uint32_t>(a), a1 = a >> 32;
        const u64 b0 = static_cast<std::uint32_t>(b), b1 = b >> 32;
        const u64 low = a0 * b0;
        const u64 middle = a1 * b0 + (low >> 32);
        const u64 upper_middle = a0 * b1 + static_cast<std::uint32_t>(middle);
        return {(upper_middle << 32) | static_cast<std::uint32_t>(low),
                a1 * b1 + (middle >> 32) + (upper_middle >> 32)};
    }
#endif

    // 通常はa,b<modulus_。Relaxedではmodulus_<2^62、a,b<2*modulus_。
    u64 multiply(u64 a, u64 b) const noexcept
    {
#if (defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC)
        const u128 value = static_cast<u128>(a) * b;
        const u128 correction = static_cast<u128>(static_cast<u64>(value) * negative_inverse_) * modulus_;
        const u128 sum = value + correction;
        const u64 result = static_cast<u64>(sum >> 64);
        if constexpr (Relaxed)
            return result;
        else
        {
            if (sum < value || result >= modulus_)
                return result - modulus_;
            return result;
        }
#else
        const auto value = product(a, b);
        const auto correction = product(value.low * negative_inverse_, modulus_);
        const u64 upper = value.high + correction.high;
        const u64 result = upper + (value.low != 0);
        if constexpr (Relaxed)
            return result; // 2*modulus_未満のまま保持し、累乗中の条件分岐を省く。
        else
        {
            // 129ビット目の桁上がりがある場合も、減算後はmodulus_未満。
            if (upper < value.high || result < upper || result >= modulus_)
                return result - modulus_;
            return result;
        }
#endif
    }

    u64 power(u64 base, u64 exponent) const noexcept
    {
        u64 result = one_;
        while (exponent)
        {
            if (exponent & 1u)
                result = multiply(result, base);
            base = multiply(base, base);
            exponent >>= 1;
        }
        return result;
    }

    u64 normalize(u64 value) const noexcept
    {
        if constexpr (Relaxed)
            return value >= modulus_ ? value - modulus_ : value;
        else
            return value;
    }

