                    const u64 remainder = magnitude % modulus_;
                    reduced = remainder ? modulus_ - remainder : 0;
                }
                else
                    reduced = static_cast<u64>(base) < modulus_ ? static_cast<u64>(base) : static_cast<u64>(base) % modulus_;
